  select 1 from public.food_catalog f where public.normalize_food_search(f.name)=public.normalize_food_search(seed.name) and coalesce(f.brand,'')=''
);

update public.food_catalog
set search_text=public.normalize_food_search(concat_ws(' ',name,brand,category,array_to_string(aliases,' ')))
where search_text='';
